// Fixride — prototype runtime. Autogenerated from scratchpad/hub-ride.html.

(function(){
  const phone = document.getElementById('phone');
  const screens = Array.from(phone.querySelectorAll('.screen'));
  const sheets = Array.from(phone.querySelectorAll('.sheet'));
  const scrim = document.getElementById('scrim');
  const toast = document.getElementById('toast');
  const toastText = document.getElementById('toastText');
  const stack = ['A1'];
  const hiddenAll = (list)=>list.forEach(e=>e.hidden=true);

  const AUTO = {
    SP: {kind:'go', to:'A1', ms:2000},
    B5: {kind:'go', to:'B6', ms:9000},
    C3: {kind:'go', to:'C4', ms:9000},
    C6: {kind:'go', to:'C7', ms:9000},
    C7: {kind:'sheet', to:'C8', ms:10000}
  };
  let autoTimer = null, bayInt = null;
  function clearAuto(){ clearTimeout(autoTimer); autoTimer=null; clearInterval(bayInt); bayInt=null; }

  function show(name, dir='fwd'){
    clearAuto();
    hiddenAll(screens);
    const el = phone.querySelector(`.screen[data-screen="${name}"]`);
    if(!el) return;
    el.hidden = false;
    el.classList.remove('enter','enter-back');
    void el.offsetWidth;
    el.classList.add(dir==='back' ? 'enter-back' : 'enter');
    el.querySelector('.main')?.scrollTo(0,0);
    closeAllOverlays();
    phone.classList.toggle('lock', name==='C1');
    phone.classList.toggle('splash', name==='SP');
    // Hide global tabbar on splash and the whole sign-up stack
    const signupScreens = new Set(['SP','A1','A2','A3','A4','A5','A6','A7','A7b','X14','X15','C1','W1','W2','W3','W4']);
    phone.setAttribute('data-signup', signupScreens.has(name) ? 'true' : 'false');
    // Active tab mapping
    const tabMap = {M1:'Trips', M2:'Trips', M3:'Help', M4:'Help', M5:'Help', M6:'Profile'};
    const activeTab = tabMap[name] || 'Home';
    document.querySelectorAll('#globalTabs .tab').forEach(t => {
      const on = t.dataset.tab === activeTab;
      t.classList.toggle('on', on);
      if(on) t.setAttribute('aria-current','page'); else t.removeAttribute('aria-current');
    });
    if(name==='C5') startBayTimer();
    const a = AUTO[name];
    if(a){
      autoTimer = setTimeout(()=>{
        if(a.kind==='go') go(a.to);
        else if(a.kind==='sheet') openSheet(a.to);
      }, a.ms);
    }
  }

  function startBayTimer(){
    const el = phone.querySelector('[data-timer="c5"]');
    if(!el) return;
    let sec = 4*60 + 12;
    function updt(){
      const m = Math.floor(sec/60), s = sec%60;
      el.textContent = m + ':' + String(s).padStart(2,'0');
      if(sec<=0){ clearInterval(bayInt); return; }
      sec--;
    }
    updt();
    bayInt = setInterval(updt, 1000);
  }
  function go(name){
    if(stack[stack.length-1]!==name){ stack.push(name); }
    show(name);
  }
  function back(){
    if(stack.length>1){ stack.pop(); show(stack[stack.length-1],'back'); }
  }
  // Sheet stack — supports stacked sheets so a nested sheet's "back/close"
  // returns to the parent instead of dismissing all the way to the screen.
  const sheetStack = [];
  // Sheets that stack on top of another instead of replacing it
  const nestedSheets = new Set(['B4a','B4b']);

  function openSheet(name){
    const sh = phone.querySelector(`[data-sheet-screen="${name}"]`);
    if(!sh) return;
    if(!nestedSheets.has(name)){
      // Replace behavior — close any currently open sheet/dialog first
      sheetStack.forEach(n => { const el = phone.querySelector(`[data-sheet-screen="${n}"]`); if(el){ el.hidden = true; el.style.zIndex = ''; }});
      sheetStack.length = 0;
    }
    sh.style.zIndex = 41 + sheetStack.length * 2;
    sh.hidden = false;
    sheetStack.push(name);
    scrim.hidden = false;
    scrim.dataset.noClose = sh.hasAttribute('data-no-scrim-close') ? '1' : '';
  }
  // Close only the topmost sheet (used by data-close / scrim click)
  function closeOverlays(){
    if(sheetStack.length === 0){
      phone.querySelectorAll('[data-sheet-screen]').forEach(s => { s.hidden = true; s.style.zIndex = ''; });
      scrim.hidden = true;
      scrim.dataset.noClose = '';
      return;
    }
    const name = sheetStack.pop();
    const el = phone.querySelector(`[data-sheet-screen="${name}"]`);
    if(el){ el.hidden = true; el.style.zIndex = ''; }
    if(sheetStack.length === 0){
      scrim.hidden = true;
      scrim.dataset.noClose = '';
    } else {
      // Reset no-close flag to whatever the new top wants
      const top = phone.querySelector(`[data-sheet-screen="${sheetStack[sheetStack.length-1]}"]`);
      scrim.dataset.noClose = top && top.hasAttribute('data-no-scrim-close') ? '1' : '';
    }
  }
  // Close every open sheet (used when navigating to a different screen)
  function closeAllOverlays(){
    phone.querySelectorAll('[data-sheet-screen]').forEach(s => { s.hidden = true; s.style.zIndex = ''; });
    sheetStack.length = 0;
    scrim.hidden = true;
    scrim.dataset.noClose = '';
  }
  function showToast(msg){
    toastText.textContent = msg;
    toast.hidden = false;
    toast.style.bottom = 'calc(var(--h-home) + 80px)';
    clearTimeout(showToast._t);
    showToast._t = setTimeout(()=>toast.hidden=true, 2600);
  }

  // delegated click handler
  phone.addEventListener('click', (ev)=>{
    const t = ev.target.closest('[data-go],[data-back],[data-sheet],[data-close],[data-perm],[data-tog],[data-toast]');
    if(!t) return;

    if(t.hasAttribute('data-toast')){ showToast(t.getAttribute('data-toast')); }
    if(t.hasAttribute('data-close')){ closeOverlays(); return; }
    if(t.hasAttribute('data-back')){ back(); return; }
    if(t.hasAttribute('data-perm')){ // A5 → shows A6 OS popup overlay
      go('A6');
      return;
    }
    if(t.hasAttribute('data-sheet')){ openSheet(t.getAttribute('data-sheet')); return; }
    if(t.hasAttribute('data-tog')){
      t.classList.toggle('on');
      const mark = t.querySelector('.mark');
      if(mark){
        if(t.classList.contains('on')){ mark.innerHTML = '<svg class="i i-16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>'; }
        else { mark.innerHTML = ''; }
      }
      return;
    }
    if(t.hasAttribute('data-toggle')){
      t.classList.toggle('sel');
      return;
    }
    if(t.hasAttribute('data-bag')){
      t.classList.toggle('on');
      const mk = t.querySelector('.mark');
      if(mk){
        if(t.classList.contains('on')){
          mk.innerHTML = '<svg class="i i-16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>';
          mk.style.background = ''; mk.style.borderWidth='';
        } else {
          mk.innerHTML = '';
          mk.style.background = 'transparent';
          mk.style.border = '1.5px solid var(--line-strong)';
        }
      }
      return;
    }
    if(t.hasAttribute('data-go')){
      const to = t.getAttribute('data-go');
      go(to);
    }
  });

  // Phone input validation (A3) — editable, error on < 10 digits
  const phoneInput = document.getElementById('phoneInput');
  const phoneField = document.getElementById('phoneField');
  const phoneHelp = document.getElementById('phoneHelp');
  const phoneSubmit = document.getElementById('phoneSubmit');
  const phoneHelpOriginal = phoneHelp ? phoneHelp.innerHTML : '';
  if(phoneInput){
    phoneInput.addEventListener('input', () => {
      // Format as XXXXX XXXXX while typing
      let v = phoneInput.value.replace(/\D/g,'').slice(0,10);
      if(v.length > 5) v = v.slice(0,5) + ' ' + v.slice(5);
      phoneInput.value = v;
      // Clear any error state as user types
      if(phoneField.classList.contains('err')){
        phoneField.classList.remove('err');
        phoneHelp.className = 'help';
        phoneHelp.innerHTML = phoneHelpOriginal;
      }
    });
    phoneSubmit.addEventListener('click', () => {
      const digits = phoneInput.value.replace(/\D/g,'');
      if(digits.length !== 10){
        phoneField.classList.add('err');
        phoneHelp.className = 'help err';
        phoneHelp.innerHTML = '<svg class="i i-16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l10 18H2L12 2z"/><path d="M12 10v4M12 17h.01"/></svg> Enter all 10 digits';
        return;
      }
      go('A4');
    });
  }

  // Code boxes (A4) — editable, success / error states
  const codeBoxes = Array.from(document.querySelectorAll('[data-code-box]'));
  const codeHelp = document.getElementById('codeHelp');
  const codeSubmit = document.getElementById('codeSubmit');
  const codeContainer = document.getElementById('codeBoxes');
  const codeHelpOriginal = codeHelp ? codeHelp.innerHTML : '';
  const EXPECTED_CODE = '381402';
  function updateCodeBoxFills(){
    codeBoxes.forEach(b => {
      b.classList.toggle('filled', !!b.value);
      // Clear error state as user types
    });
    if(codeContainer.classList.contains('err')){
      codeContainer.classList.remove('err');
      codeHelp.className = 'help';
      codeHelp.innerHTML = codeHelpOriginal;
    }
  }
  codeBoxes.forEach((box, i) => {
    box.addEventListener('input', () => {
      box.value = box.value.replace(/\D/g,'').slice(0,1);
      updateCodeBoxFills();
      if(box.value && i < codeBoxes.length - 1){
        codeBoxes[i+1].focus();
        codeBoxes[i+1].select();
      }
    });
    box.addEventListener('keydown', (e) => {
      if(e.key === 'Backspace' && !box.value && i > 0){
        codeBoxes[i-1].focus();
        codeBoxes[i-1].select();
      }
    });
    box.addEventListener('focus', () => box.select());
  });
  if(codeSubmit){
    codeSubmit.addEventListener('click', () => {
      const code = codeBoxes.map(b => b.value).join('');
      if(code === EXPECTED_CODE){
        codeContainer.classList.remove('err');
        codeContainer.classList.add('ok');
        codeHelp.className = 'help ok';
        codeHelp.innerHTML = '<svg class="i i-16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg> Verified';
        setTimeout(() => { go('A5'); codeContainer.classList.remove('ok'); codeHelp.className = 'help'; codeHelp.innerHTML = codeHelpOriginal; }, 650);
      } else {
        codeContainer.classList.add('err');
        codeHelp.className = 'help err';
        codeHelp.innerHTML = '<svg class="i i-16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l10 18H2L12 2z"/><path d="M12 10v4M12 17h.01"/></svg> That code is wrong. 2 tries left.';
      }
    });
  }

  // Share chips (B7a) — toggle teal stroke
  phone.querySelectorAll('[data-share]').forEach(b => b.addEventListener('click', () => {
    b.classList.toggle('sel');
  }));

  // Payment option radios (W3)
  phone.querySelectorAll('[data-pay]').forEach(b => b.addEventListener('click', () => {
    phone.querySelectorAll('[data-pay]').forEach(x => x.classList.remove('sel'));
    b.classList.add('sel');
  }));

  // Web-form language chips (W2)
  phone.querySelectorAll('[data-wa-lang]').forEach(b => b.addEventListener('click', () => {
    phone.querySelectorAll('[data-wa-lang]').forEach(x => x.classList.remove('sel'));
    b.classList.add('sel');
  }));

  // "Which bag?" chip row (M4)
  phone.querySelectorAll('[data-which-bag]').forEach(b => b.addEventListener('click', () => {
    phone.querySelectorAll('[data-which-bag]').forEach(x => x.classList.remove('sel'));
    b.classList.add('sel');
  }));

  // iOS switch (M6)
  phone.querySelectorAll('[data-switch]').forEach(b => b.addEventListener('click', () => {
    b.classList.toggle('on');
    b.setAttribute('aria-checked', b.classList.contains('on') ? 'true' : 'false');
  }));

  // Save-as chip group (A7b)
  phone.querySelectorAll('[data-save-as]').forEach(b => b.addEventListener('click', () => {
    phone.querySelectorAll('[data-save-as]').forEach(x => x.classList.remove('sel'));
    b.classList.add('sel');
  }));

  // Star rating (C9)
  const starBtns = phone.querySelectorAll('#stars button');
  starBtns.forEach((b,i)=>b.addEventListener('click', ()=>{
    starBtns.forEach((x,j)=>x.setAttribute('aria-pressed', j<=i ? 'true':'false'));
  }));

  // scrim close for overlays (unless the open sheet forbids it)
  scrim.addEventListener('click', ()=>{
    if(scrim.dataset.noClose === '1') return;
    closeOverlays();
  });

  // Steppers
  phone.querySelectorAll('.stepper').forEach(st=>{
    const val = st.querySelector('.val');
    const [minus, plus] = st.querySelectorAll('button');
    minus.addEventListener('click', ()=>{
      const n = Math.max(0, parseInt(val.textContent,10)-1);
      val.textContent = n;
    });
    plus.addEventListener('click', ()=>{
      const n = parseInt(val.textContent,10)+1;
      val.textContent = n;
    });
  });

  // Language tiles (A2 — now .lang-card)
  const langs = phone.querySelectorAll('#langGroup [role="radio"]');
  langs.forEach(r=>r.addEventListener('click', ()=>{
    langs.forEach(x=>{ x.classList.remove('selected'); x.setAttribute('aria-checked','false'); x.querySelector('.mark').innerHTML=''; });
    r.classList.add('selected'); r.setAttribute('aria-checked','true');
    r.querySelector('.mark').innerHTML = '<svg class="i i-16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>';
  }));

  // Resend countdown on A4
  let r = 24;
  const resendEl = document.getElementById('resend');
  function tick(){
    if(!resendEl) return;
    r--;
    if(r<=0){ resendEl.textContent = ''; resendEl.parentElement.innerHTML = '<a href="#" style="color:var(--accent); font-weight:600">Resend code</a>'; return; }
    resendEl.textContent = '0:' + String(r).padStart(2,'0');
    setTimeout(tick, 1000);
  }
  setTimeout(tick, 1000);

  // Boot
  show('SP');
})();
